function trasforma(input){
  var m = String(input.Data || '').match(/(\d{1,2})\D(\d{1,2})\D(\d{2,4})/);
  if (!m) return { data: null };
  var y = m[3].length === 2 ? '20' + m[3] : m[3];
  return { data: y + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2) };
}

