import re

def trasforma(campi):
    m = re.search(r'(\d{1,2})\D(\d{1,2})\D(\d{2,4})', str(campi.get('Data') or ''))
    if not m:
        return {'data': None}
    g, mm, a = m.groups()
    a = '20' + a if len(a) == 2 else a
    return {'data': f'{a}-{int(mm):02d}-{int(g):02d}'}
